// eventNamespace mirrors upstream client-go's WithEventNamespace
// semantics (event_expansion.go's NamespaceIfScoped): the request targets
// the *event's own* namespace, not the client's. The distinction matters
// because record.EventBroadcaster builds its sink as Events("") -- with
// c.ns alone, every write went to the cluster-scoped /api/v1/events path
// and silently failed (found live: zero Events stored while the real
// controllers were demonstrably reconciling).
func (c *events) eventNamespace(eventNS string) *events {
	if eventNS == "" || eventNS == c.ns {
		return c
	}
	return NewEvents(c.client, eventNS)
}

